// :probe — generated by scripts/harness/probe-kotlin.ts from the consumer's token index; depends on :tokens
// (design § 2). A module of its own, so a member the generator left `internal` is not readable from here.
// Every read is inside a @Composable function.

import org.jetbrains.kotlin.gradle.tasks.KotlinCompile

plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.compose)
}

val laneDir: File = providers.environmentVariable("HARNESS_LANE_DIR").orNull?.let(::File)
    ?: throw GradleException("HARNESS_LANE_DIR is not set; run harness/android/lane.ts, which writes the source lists")

fun laneFiles(name: String): List<File> {
    val list = File(laneDir, name)
    if (!list.isFile) throw GradleException("harness lane: $list does not exist")
    val files = list.readLines().filter { it.isNotBlank() }.map(::File)
    val missing = files.filterNot { it.isFile }
    if (missing.isNotEmpty()) throw GradleException("harness lane: ${missing.size} source file(s) listed in $name do not exist; first: ${missing.first()}")
    return files
}

android {
    // Outside the reserved packages (com.designerpunk.*), so design § 9's scan does not flag the probe's own package.
    namespace = "dpharness.probe"
    compileSdk = libs.versions.compile.sdk.get().toInt()
    defaultConfig {
        minSdk = libs.versions.min.sdk.get().toInt()
    }
    buildFeatures {
        compose = true
    }
}

dependencies {
    implementation(project(":tokens"))
    implementation(platform(libs.compose.bom))
    implementation(libs.bundles.compose)
    implementation(libs.colormath)
}

val probeFiles = laneFiles("probe.sources")
val expectedFile = File(laneDir, "probe-expected.txt")

tasks.withType<KotlinCompile>().matching { it.name == "compileDebugKotlin" }.configureEach {
    setSource(files(probeFiles))
    doFirst {
        // One count line per group of required reads (design § 3). `m` comes from probe-expected.txt, which
        // probe-kotlin.ts computed from the inputs (the index, the shared module, the product source); `n` is the
        // number of marker comments in the sources this module was given. This task PRINTS and never throws: the lane
        // reads the lines into the run file's `checks`, and the comparator fails the context when `n` differs from `m`.
        // The lines appear only when this compile runs; while :tokens fails, Gradle skips it and the lane prints the
        // blocked line instead.
        if (!expectedFile.isFile) throw GradleException("probe: $expectedFile does not exist")
        val expected = expectedFile.readLines().filter { it.contains('=') }.associate { it.substringBefore('=') to it.substringAfter('=').trim() }
        fun m(key: String): Int = expected[key]?.toIntOrNull() ?: throw GradleException("probe: $expectedFile has no $key line")
        val lines = probeFiles.flatMap { it.readLines() }
        fun n(marker: String): Int = lines.count { it.contains(marker) }
        println("probe: read ${n("// @index ")} of ${m("index-names")} index names")
        println("probe: instances read ${n("// @instance ")} of ${m("instances")}")
        println("probe: product read ${n("// @product ")} of ${m("product")}")
        println("probe: provider read ${n("// @provider ")} of ${m("provider")}")
    }
}
